const searchChunks = `-- name: SearchChunks :many
SELECT id, content, (embedding <=> $1::vector)::float8 AS distance FROM chatbot.knowledge_chunks
WHERE tenant_id = $2 AND bot_id = $3 ORDER BY embedding <=> $1::vector LIMIT 4
`

type SearchChunksParams struct {
	Query    string
	TenantID uuid.UUID
	BotID    uuid.UUID
}

type SearchChunksRow struct {
	ID       uuid.UUID
	Content  string
	Distance float64
}

// Only this tenant's bot's own knowledge, nearest first.
func (q *Queries) SearchChunks(ctx context.Context, arg SearchChunksParams) ([]SearchChunksRow, error) {
	rows, err := q.db.Query(ctx, searchChunks, arg.Query, arg.TenantID, arg.BotID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchChunksRow
	for rows.Next() {
		var i SearchChunksRow
		if err := rows.Scan(&i.ID, &i.Content, &i.Distance); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

