const upsertQualification = `-- name: UpsertQualification :exec

INSERT INTO chatbot.qualifications (tenant_id, conversation_id, answers, score, status, crm_company_id) VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (tenant_id, conversation_id) DO UPDATE SET answers = EXCLUDED.answers, score = EXCLUDED.score, status = EXCLUDED.status, crm_company_id = coalesce(EXCLUDED.crm_company_id, chatbot.qualifications.crm_company_id)
`

type UpsertQualificationParams struct {
	TenantID       uuid.UUID
	ConversationID uuid.UUID
	Answers        []byte
	Score          *int32
	Status         string
	CrmCompanyID   *uuid.UUID
}

// Qualification, handoffs.
func (q *Queries) UpsertQualification(ctx context.Context, arg UpsertQualificationParams) error {
	_, err := q.db.Exec(ctx, upsertQualification,
		arg.TenantID,
		arg.ConversationID,
		arg.Answers,
		arg.Score,
		arg.Status,
		arg.CrmCompanyID,
	)
	return err
}
